const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let records=[],editing=null,images=[],uploading=false,dirty=false,deleting=null;
const notice=(t)=>{$('#notice').textContent=t;$('#notice').hidden=!t};
async function api(path,opts={}){const res=await fetch(path,opts);let d;try{d=await res.json()}catch{throw Error('服務暫時無法使用。')}if(!res.ok)throw Error(d.error||'操作失敗。');return d}
const post=(path,data)=>api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});
async function refresh(){records=await api('/api/records?admin=1');renderList()}
function renderList(){const q=$('#adminSearch').value.trim().toLowerCase(),t=$('#adminType').value;const filtered=records.filter(r=>(!t||r.type===t)&&(r.title+r.officialTitle).toLowerCase().includes(q));$('#adminList').innerHTML=filtered.map(r=>`<article class="admin-row">${r.images?.length?`<img class="admin-thumb" src="${esc(r.images[0].url)}" alt="">`:`<span class="admin-thumb">${r.type==='小說'?'文':'畫'}</span>`}<div><h3>${esc(r.title)}<span class="published-badge">${r.published?'已公開':'草稿'}</span></h3><p>${esc(r.type)} / ${esc(r.number)}${r.sample?' / 示範內容':''}${r.mainComic?' / 首頁主篇':''}<br>更新 ${esc((r.updated||'2026-10-01').slice(0,10))}</p></div><div class="admin-actions"><button data-edit="${esc(r.id)}">編輯</button>${r.published?`<a class="button" href="/#read/${encodeURIComponent(r.id)}" target="_blank" rel="noopener">閱讀 ↗</a>`:''}<button class="danger" data-delete="${esc(r.id)}">刪除</button></div></article>`).join('')||'<div class="empty-state">尚無符合的作品。使用上方按鈕新增。</div>';document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openEditor(records.find(r=>r.id===b.dataset.edit)));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{deleting=b.dataset.delete;$('#deleteDialog').showModal()})}
async function enter(){await refresh();$('#login').hidden=true;$('#dashboard').hidden=false;notice('')}
$('#loginForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await post('/api/login',{password:$('#password').value});$('#password').value='';await enter()}catch(err){notice(err.message)}finally{b.disabled=false}};
$('#logout').onclick=async()=>{await post('/api/logout',{});location.reload()};
$('#adminSearch').oninput=renderList;$('#adminType').onchange=renderList;
document.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>openEditor({type:b.dataset.new}));
function openEditor(r){editing=r.id?r:null;images=(r.images||[]).map(x=>({...x}));$('#dashboard').hidden=true;$('#editor').hidden=false;$('#editorTitle').textContent=(r.id?'編輯':'新增')+(r.type==='插畫'?'圖片':r.type);$('#editForm').dataset.type=r.type;for(const key of ['title','officialTitle','number','summary','assessment'])$('#'+key).value=r[key]||'';$('#tagsInput').value=(r.tags||[]).join('，');$('#bodyInput').value=r.body||'';for(const key of ['published','restricted','mainComic','sample'])$('#'+key).checked=!!r[key];$('#bodyField').hidden=r.type!=='小說';$('#mediaField').hidden=r.type==='小說';$('#mainComicField').hidden=r.type!=='漫畫';$('#mediaInput').multiple=r.type==='漫畫';$('#mediaInput').value='';$('#saveStatus').textContent='';$('#uploadStatus').textContent='';renderImages();dirty=false;window.scrollTo(0,0)}
$('#editForm').oninput=()=>dirty=true;
$('#cancelEdit').onclick=()=>{if(uploading)return notice('請等待圖片上傳完成。');if(dirty&&!confirm('有尚未保存的修改，確定返回嗎？'))return;$('#editor').hidden=true;$('#dashboard').hidden=false;dirty=false;notice('')};
function renderImages(){$('#mediaList').innerHTML=images.map((m,i)=>`<div class="media-item"><img src="${esc(m.url)}" alt="第 ${i+1} 頁"><div class="media-info">P${String(i+1).padStart(2,'0')} / ${esc(m.name||'圖片')}</div><div class="media-actions"><button type="button" data-up="${i}" ${i===0?'disabled':''} aria-label="第 ${i+1} 頁往前移">↑</button><button type="button" data-down="${i}" ${i===images.length-1?'disabled':''} aria-label="第 ${i+1} 頁往後移">↓</button><button type="button" data-remove="${i}">移除</button></div></div>`).join('');document.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>move(+b.dataset.up,-1));document.querySelectorAll('[data-down]').forEach(b=>b.onclick=()=>move(+b.dataset.down,1));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{images.splice(+b.dataset.remove,1);dirty=true;renderImages()})}
function move(i,d){[images[i],images[i+d]]=[images[i+d],images[i]];dirty=true;renderImages()}
async function compress(file){if(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type))throw Error('僅支援 JPG、PNG、WebP、GIF。');if(file.type==='image/gif'){if(file.size>1800000)throw Error('GIF 請小於 1.8 MB。');return file}const bitmap=await createImageBitmap(file);const scale=Math.min(1,2200/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let blob=await new Promise(r=>canvas.toBlob(r,'image/webp',.9));if(blob.size>1800000)blob=await new Promise(r=>canvas.toBlob(r,'image/webp',.7));if(blob.size>1800000)throw Error('圖片仍太大，請先縮小後再上傳。');return blob}
async function upload(files){if(uploading)return;files=[...files].sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true}));if($('#editForm').dataset.type==='插畫'&&files.length>1)return notice('單張插畫請一次選一張；多頁作品可使用漫畫類型。');if(images.length+files.length>100)return notice('每篇最多 100 頁。');uploading=true;$('#save').disabled=true;$('#mediaInput').disabled=true;notice('');let done=0;try{for(const file of files){$('#uploadStatus').textContent=`上傳中 ${done+1} / ${files.length}：${file.name}`;const blob=await compress(file);const m=await api('/api/media',{method:'POST',headers:{'Content-Type':blob.type},body:blob});images.push({...m,name:file.name});done++;dirty=true;renderImages()}$('#uploadStatus').textContent=`已上傳 ${done} 張。請按「保存作品」完成歸檔。`}catch(e){notice(e.message);$('#uploadStatus').textContent=`已完成 ${done} 張，其餘請重新選擇上傳。`}finally{uploading=false;$('#save').disabled=false;$('#mediaInput').disabled=false;$('#mediaInput').value=''}}
$('#mediaInput').onchange=e=>upload(e.target.files);const drop=$('.upload-area');drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging')};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragging');upload(e.dataTransfer.files)};
function payload(){return {id:editing?.id,type:$('#editForm').dataset.type,title:$('#title').value,officialTitle:$('#officialTitle').value,number:$('#number').value,summary:$('#summary').value,body:$('#bodyInput').value,tags:$('#tagsInput').value.split(/[,，]/).map(x=>x.trim()).filter(Boolean),images,assessment:$('#assessment').value,published:$('#published').checked,restricted:$('#restricted').checked,mainComic:$('#mainComic').checked,sample:$('#sample').checked}}
$('#editForm').onsubmit=async e=>{e.preventDefault();if(uploading)return;$('#save').disabled=true;$('#saveStatus').textContent='正在保存…';try{await post('/api/records',payload());dirty=false;await refresh();$('#editor').hidden=true;$('#dashboard').hidden=false;notice('作品已保存。'+(payload().published?'網站已同步更新。':'目前保存為草稿。'));window.scrollTo(0,0)}catch(e){$('#saveStatus').textContent=e.message}finally{$('#save').disabled=false}};
$('#preview').onclick=()=>{const r=payload();$('#previewContent').innerHTML=`<p class="eyebrow">作品預覽 / 尚未保存</p><h2>${esc(r.title||'未命名作品')}</h2><p>${esc(r.summary)}</p>${r.type==='小說'?`<div class="prose">${r.body.split(/\n\s*\n/).map(p=>`<p>${esc(p)}</p>`).join('')}</div>`:images.map(m=>`<img src="${esc(m.url)}" alt="${esc(m.name)}">`).join('')}`;$('#previewDialog').showModal()};$('#closePreview').onclick=()=>$('#previewDialog').close();
$('#cancelDelete').onclick=()=>$('#deleteDialog').close();$('#confirmDelete').onclick=async()=>{$('#confirmDelete').disabled=true;try{await api('/api/records/'+encodeURIComponent(deleting),{method:'DELETE'});$('#deleteDialog').close();await refresh();notice('作品已刪除。')}catch(e){notice(e.message)}finally{$('#confirmDelete').disabled=false}};
$('#changePassword').onclick=()=>$('#passwordDialog').showModal();$('#closePassword').onclick=()=>$('#passwordDialog').close();$('#passwordForm').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await post('/api/password',{password:$('#newPassword').value});$('#newPassword').value='';$('#passwordDialog').close();notice('管理密碼已更新。')}catch(err){$('#passwordStatus').textContent=err.message}finally{e.submitter.disabled=false}};
$('#backup').onclick=async()=>{const b=$('#backup');b.disabled=true;notice('正在準備備份，包含作品文字與圖片。');try{const backup=structuredClone(records);for(const r of backup)for(const m of r.images||[]){const res=await fetch(m.url);if(!res.ok)throw Error('圖片讀取失敗。');const blob=await res.blob();m.data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)})}const blob=new Blob([JSON.stringify({version:1,exported:new Date().toISOString(),records:backup},null,2)],{type:'application/json'});const href=URL.createObjectURL(blob);const a=document.createElement('a');a.href=href;a.download='41-archive-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(href),30000);notice('備份已下載，包含草稿、公開作品與圖片。')}catch(e){notice('備份未完成：'+e.message)}finally{b.disabled=false}};
window.addEventListener('beforeunload',e=>{if(dirty||uploading){e.preventDefault();e.returnValue=''}});
(async()=>{try{const r=await api('/api/session');if(r.authenticated)await enter()}catch(e){notice(e.message)}})();
